"""Rows bought as gear: ware, armor, weapons, vehicles, commlinks, gear, drugs, lifestyles."""

from __future__ import annotations

import uuid
from typing import Literal

from pydantic import BaseModel, Field


class CyberwareInstall(BaseModel):
    id: str = Field(default_factory=lambda: str(uuid.uuid4()))
    ware_id: str
    #: Selected ammunition for the weapon generated by this implant.
    loaded_ammo_id: str | None = None
    rating: int = 1
    grade: str = "Standard"
    wireless: bool = True
    parent_id: str | None = None
    included: bool = False
    side: str | None = None
    # `<selectcyberware>`: the implant this one is keyed to (Implant Medic,
    # Nanohive Soft). A label, like Chummer's `<extra>` — it grants nothing.
    extra: str | None = None
    #: the price picked for a `Variable(lo-hi)` piece (Biosculpting)
    cost: int | None = None
    #: bought through the Black Market Pipeline: 10% off (Chummer's
    #: `<discountedcost>`, which the quality's categories allow)
    discounted: bool = False
    #: `<essdiscount>`: a percentage off this piece's essence, as the GM
    #: allows under `<allowcyberwareessdiscounts>` (Chummer's `ESSDiscount`,
    #: -100 to 100; negative costs more)
    ess_discount: int = Field(default=0, ge=-100, le=100)
    #: Prototype Transhuman (RF p.159): whether this bioware is one the
    #: allowance waives, as the player ticked it (Chummer's
    #: `<prototypetranshuman>`). None on every piece: nothing ticked yet, and
    #: the engine picks the set that waives the most.
    prototype_transhuman: bool | None = None
    #: the `...nonretroactive` essence multipliers this piece holds in career
    #: (Chummer's `<extraessadditivemultiplier>`, added to the grade's, and
    #: `<extraessmultiplicativemultiplier>`): what they were on entering
    #: career, or when it was bought there. None until the engine keeps them,
    #: on the first career compute that sees the piece; dropped in chargen.
    ess_extra_additive: float | None = None
    ess_extra_multiplicative: float | None = None
    #: the player's own note on this row (Chummer's `<notes>`); nothing is
    #: computed from it
    notes: str = ""


class ArmorInstall(BaseModel):
    id: str = Field(default_factory=lambda: str(uuid.uuid4()))
    armor_id: str
    rating: int = 1
    #: the price picked for a `Variable(lo-hi)` piece (Clothing)
    cost: int | None = None
    equipped: bool = True
    wireless: bool = True
    #: bought through the Black Market Pipeline: 10% off (Chummer's
    #: `<discountedcost>`, which the quality's categories allow)
    discounted: bool = False
    #: the player's own note on this row (Chummer's `<notes>`); nothing is
    #: computed from it
    notes: str = ""
    #: the player's own name for this one (Chummer's `<armorname>`), shown beside
    #: the catalogue's
    nickname: str = ""
    #: where the player keeps it: the id of one of the character's
    #: `armor_locations` (Chummer's `<location>`, a `<armorlocations>` guid)
    location: str | None = None


class ArmorModInstall(BaseModel):
    id: str = Field(default_factory=lambda: str(uuid.uuid4()))
    mod_id: str
    parent_id: str | None = None
    included: bool = False
    rating: int = 1
    wireless: bool = True
    # Custom Fit (Stack) `<selectarmor>`: the catalog name of the armor this
    # piece was tailored to stack with (Chummer's `<extra>`)
    stack_with: str = ""


class WeaponInstall(BaseModel):
    id: str = Field(default_factory=lambda: str(uuid.uuid4()))
    weapon_id: str
    qty: int = 1
    loaded_ammo_id: str | None = None
    #: comes with a drone's own entry: free, and not the player's to remove
    included: bool = False
    #: Bought for free in Chummer (`<cost>0`), independently of its accessories.
    #: Still removable and otherwise treated as a normal purchased weapon.
    free: bool = False
    #: bought through the Black Market Pipeline: 10% off (Chummer's
    #: `<discountedcost>`, which the quality's categories allow)
    discounted: bool = False
    #: the player's own note on this row (Chummer's `<notes>`); nothing is
    #: computed from it
    notes: str = ""


class VehicleModInstall(BaseModel):
    id: str = Field(default_factory=lambda: str(uuid.uuid4()))
    mod_id: str
    parent_id: str | None = None
    included: bool = False
    rating: int = 1
    #: Chummer's "free item" tick: bought, but at no cost (`<cost>0`).
    #: Unlike `included`, it takes slots and the player may remove it.
    free: bool = False


class WeaponMountInstall(BaseModel):
    id: str = Field(default_factory=lambda: str(uuid.uuid4()))
    parent_id: str | None = None
    size_id: str = ""
    visibility_id: str = ""
    flexibility_id: str = ""
    control_id: str = ""
    included: bool = False
    weapon_install_id: str | None = None
    allowedweapons: str = ""


class WeaponAccessoryInstall(BaseModel):
    id: str = Field(default_factory=lambda: str(uuid.uuid4()))
    accessory_id: str
    parent_id: str | None = None
    included: bool = False
    #: Bought for free (`<cost>0`); still occupies a mount and can be removed.
    free: bool = False
    rating: int = 1
    mount: str = ""
    #: on the weapon (Chummer's `<equipped>`): one taken off is still owned
    #: and paid for, and keeps its mount, but adds nothing to the weapon
    equipped: bool = True
    #: bought through the Black Market Pipeline: 10% off (Chummer's
    #: `<discountedcost>`, which the quality's categories allow)
    discounted: bool = False
    #: the player's own note on this row (Chummer's `<notes>`); nothing is
    #: computed from it
    notes: str = ""


class CommlinkInstall(BaseModel):
    id: str = Field(default_factory=lambda: str(uuid.uuid4()))
    gear_id: str
    rating: int = 1
    #: the headware Commlink it is implanted in (SR5 p.451)
    parent_id: str | None = None
    #: how many alike — a stack of burner Meta Links
    qty: int = Field(default=1, ge=1, le=999)
    #: bought through the Black Market Pipeline: 10% off (Chummer's
    #: `<discountedcost>`, which the quality's categories allow)
    discounted: bool = False
    #: the player's own note on this row (Chummer's `<notes>`); nothing is
    #: computed from it
    notes: str = ""
    #: the player's own name for this one (Chummer's `<gearname>`), shown beside
    #: the catalogue's
    nickname: str = ""
    #: where the player keeps it: the id of one of the character's
    #: `gear_locations` (Chummer's `<location>`, a `<gearlocations>` guid).
    #: Only a row of its own has one; what is put inside another goes where
    #: that goes.
    location: str | None = None


class GearInstall(BaseModel):
    id: str = Field(default_factory=lambda: str(uuid.uuid4()))
    gear_id: str
    rating: int = 1
    qty: int = 1
    parent_id: str | None = None
    included: bool = False
    capacity_override: str | None = None
    array_order: list[str] = Field(default_factory=list)
    #: Cyberdecks only: the attribute Overclocker raises on this deck (Chummer's
    #: `<overclocked>`) — attack / sleaze / dataprocessing / firewall, or "none".
    #: Left unset on every deck, the highest-rated deck's Attack gets it.
    overclocked: Literal["attack", "sleaze", "dataprocessing", "firewall", "none"] | None = None
    extra: str | None = None
    active: bool = False  # drugs/toxins: effect currently applied
    # Cyberdeck programs only; missing on old saves means the former all-running
    # behavior. Purchase/move UI explicitly stops new programs. RCC rules differ.
    running: bool = True
    # Imported Electronic Parts can be fractional packs. None means qty sales
    # lots; a value records acquired quarter-packs per parent, before consumption.
    purchased_parts_units: int | None = Field(default=None, ge=0, le=100000)
    # Cyberdeck modules only; this is not generic gear equipment management.
    equipped: bool = True
    #: the price picked for a `Variable(lo-hi)` item (a Custom Item, a
    #: Commlink App), and a Custom Item's own name
    cost: int | None = None
    name: str | None = Field(default=None, max_length=200)
    #: bought through the Black Market Pipeline: 10% off (Chummer's
    #: `<discountedcost>`, which the quality's categories allow)
    discounted: bool = False
    #: the player's own note on this row (Chummer's `<notes>`); nothing is
    #: computed from it
    notes: str = ""
    #: the player's own name for this one, shown beside the catalogue's
    #: (Chummer's `<gearname>`, a vehicle's or drone's `<vehiclename>`) — not
    #: `name`, which is what a Custom Item is
    nickname: str = ""
    #: where the player keeps it: the id of one of the character's
    #: `gear_locations` (Chummer's `<location>`, a `<gearlocations>` guid).
    #: Only a row of its own under `<gears>` has one, not a vehicle or drone;
    #: what is put inside another goes where that goes.
    location: str | None = None


class StorageLocation(BaseModel):
    """A place the player keeps things in — a backpack, a safehouse, a car
    (Chummer's `<gearlocations>` / `<armorlocations>`). Its id is Chummer's
    `<guid>`, which the rows name as their `location`; nothing is computed
    from where a thing is."""

    id: str = Field(default_factory=lambda: str(uuid.uuid4()), max_length=64)
    name: str = Field(default="", max_length=200)
    #: the player's own note on it (Chummer's `<notes>`)
    notes: str = ""


class CustomDrugPart(BaseModel):
    """One component in a mixed drug, at the level it was added at."""

    component_id: str
    level: int = 0


class CustomDrugInstall(BaseModel):
    """A drug the character cooked rather than bought (CF p.190).

    It has no catalog entry — the parts are the drug — so unlike every other
    piece of gear it carries its own name.
    """

    id: str = Field(default_factory=lambda: str(uuid.uuid4()))
    name: str = ""
    grade: str = "Standard"
    qty: int = 1
    active: bool = False  # effect currently applied, like GearInstall.active
    parts: list[CustomDrugPart] = Field(default_factory=list)


class LifestyleInstall(BaseModel):
    id: str = Field(default_factory=lambda: str(uuid.uuid4()))
    lifestyle_id: str
    months: int = 1
    #: Points bought above the lifestyle's own Comforts / Neighborhood /
    #: Security (RF p.219, Chummer's `<comforts>` / `<area>` / `<security>`).
    comforts: int = 0
    area: int = 0
    security: int = 0
    quality_ids: list[str] = Field(default_factory=list)
    quality_extras: dict[str, str] = Field(default_factory=dict)
    #: the player's own note on this row (Chummer's `<notes>`); nothing is
    #: computed from it
    notes: str = ""


class ElectronicPartsSupply(BaseModel):
    """Explicit acquisition; quantities are quarter-packs, never currency."""

    id: str = Field(default_factory=lambda: str(uuid.uuid4()))
    kind: Literal["salvaged", "equipment", "gm"] = "salvaged"
    units: int = Field(ge=1, le=100000)
    note: str = Field(default="", max_length=500)
    equipment_id: str | None = None


class ElectronicPartsAllocation(BaseModel):
    source_id: str
    units: int = Field(ge=1, le=100000)


class ElectronicModificationRecord(BaseModel):
    id: str = Field(default_factory=lambda: str(uuid.uuid4()))
    modification_id: str
    host_id: str
    gear_id: str
    status: Literal["pending", "completed", "historical", "cancelled"] = "pending"
    required_units: int = Field(default=0, ge=0, le=100000)
    allocations: list[ElectronicPartsAllocation] = Field(default_factory=list, max_length=100)
    # Backend freezes these values when construction is confirmed. Later
    # array/quality edits cannot consume or refund parts.
    host_snapshot: dict[str, int] = Field(default_factory=dict, max_length=10)
    rule_version: Literal[1] = 1
    note: str = Field(default="", max_length=500)
